-- Generated by ekos-lakehouse (RFC 0195): `invoiced` in gold__invoices_by_month reconciles to silver.
with mart as (
    select sum("invoiced") as v from {{ ref('gold__invoices_by_month') }}
),

silver as (
    select sum("C_INVOICE"."GRANDTOTAL") as v
    from {{ ref('ADEMPIERE__C_INVOICE') }} as "C_INVOICE"
    where "C_INVOICE"."DOCSTATUS" = 'CO'
        and "C_INVOICE"."ISSOTRX" = true
)

select mart.v as mart_total, silver.v as silver_total
from mart, silver
where mart.v is distinct from silver.v
